import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
aoi_center = ee.Geometry.Point([106.82, -6.4])  # Depok vicinity
geom = aoi_center.buffer(15000).bounds()  # ~30 km box around Depok
scale = 1000

def mask_landsat_sr(img):
    qa = img.select('QA_PIXEL')
    mask = (qa.bitwiseAnd(1 << 0).eq(0)  # fill
            .And(qa.bitwiseAnd(1 << 1).eq(0))  # dilated
            .And(qa.bitwiseAnd(1 << 2).eq(0))  # cirrus
            .And(qa.bitwiseAnd(1 << 3).eq(0))  # cloud
            .And(qa.bitwiseAnd(1 << 4).eq(0))  # shadow
            .And(qa.bitwiseAnd(1 << 5).eq(0))) # snow
    return img.updateMask(mask)

def scale_sr(img):
    optical = img.select('SR_B.*').multiply(0.0000275).add(-0.2)
    return img.addBands(optical, overwrite=True)

def rename_to_red_nir(img, sensor):
    if sensor in ('LT04', 'LT05', 'LE07'):
        return img.select(['SR_B3','SR_B4'], ['red','nir'])
    elif sensor in ('LC08', 'LC09'):
        return img.select(['SR_B4','SR_B5'], ['red','nir'])
    else:
        return img  # should not happen

def prep_collection(collection_id, sensor, start, end):
    col = (ee.ImageCollection(collection_id)
           .filterDate(start, end)
           .filterBounds(geom))
    # Check quickly if empty
    if col.size().getInfo() == 0:
        return ee.ImageCollection([])
    col = col.map(mask_landsat_sr).map(scale_sr).map(lambda im: rename_to_red_nir(im, sensor))
    col = col.map(lambda im: im.normalizedDifference(['nir','red']).rename('ndvi'))
    return col

def build_year_collection(year, widen=False):
    # Primary window: exact year; Fallback: ±1 year (3-year window)
    if not widen:
        start = ee.Date.fromYMD(year, 1, 1)
        end   = ee.Date.fromYMD(year, 12, 31)
    else:
        start = ee.Date.fromYMD(year-1, 1, 1)
        end   = ee.Date.fromYMD(year+1, 12, 31)
    # Sensor candidates by era
    if year < 1999:
        candidates = [('LANDSAT/LT05/C02/T1_L2','LT05'),
                      ('LANDSAT/LT04/C02/T1_L2','LT04')]
    elif year < 2013:
        candidates = [('LANDSAT/LT05/C02/T1_L2','LT05'),
                      ('LANDSAT/LE07/C02/T1_L2','LE07')]
    else:
        candidates = [('LANDSAT/LC08/C02/T1_L2','LC08'),
                      ('LANDSAT/LE07/C02/T1_L2','LE07')]
    merged = ee.ImageCollection([])
    total_imgs = 0
    for cid, sensor in candidates:
        col_raw = ee.ImageCollection(cid).filterDate(start, end).filterBounds(geom)
        cnt = col_raw.size().getInfo()
        if cnt and cnt > 0:
            total_imgs += cnt
            merged = merged.merge(prep_collection(cid, sensor, start, end))
    return merged, total_imgs

def year_stats(year):
    # Build collection; try fallback if empty
    col, raw_count = build_year_collection(year, widen=False)
    if col.size().getInfo() == 0:
        col, raw_count_fb = build_year_collection(year, widen=True)
        raw_count = raw_count_fb
    if col.size().getInfo() == 0:
        return {'status':'C1', 'year':year}
    # Composite NDVI (median)
    ndvi = col.median().select('ndvi')
    # Base grid count at scale
    baseCount = ee.Image.constant(1).rename('one').reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale, maxPixels=1e9
    ).get('one').getInfo()
    if baseCount is None or baseCount == 0:
        return {'status':'C2', 'year':year}
    # Valid pixels after masking
    validCount = ndvi.reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale, maxPixels=1e9
    ).get('ndvi').getInfo()
    if validCount is None:
        return {'status':'C3', 'year':year}
    if int(validCount) == 0:
        return {'status':'C2', 'year':year}
    # Vegetation count (NDVI > 0.3)
    vegCount = ndvi.gt(0.3).reduceRegion(
        reducer=ee.Reducer.sum(), geometry=geom, scale=scale, maxPixels=1e9
    ).get('ndvi').getInfo()
    if vegCount is None:
        return {'status':'C3', 'year':year}
    vegFrac = float(vegCount) / float(validCount)
    if math.isnan(vegFrac) or vegFrac < 0 or vegFrac > 1:
        return {'status':'C3', 'year':year}
    masked_pct = (1.0 - float(validCount)/float(baseCount)) * 100.0
    return {
        'status':'OK', 'year':year, 'images': int(raw_count),
        'base': int(baseCount), 'valid': int(validCount),
        'masked_pct': masked_pct, 'veg_px': int(vegCount),
        'veg_frac': vegFrac
    }

try:
    # AOI area for reference
    area_km2 = geom.area(scale=1).getInfo() / 1e6
    print(f"AOI km²: {area_km2:.1f}")

    y1, y2 = 1990, 2019
    s1 = year_stats(y1)
    s2 = year_stats(y2)

    # Handle failure cases
    if s1.get('status') != 'OK' or s2.get('status') != 'OK':
        # Print concise reason(s)
        if s1.get('status') != 'OK':
            print(f"{y1} Images: 0")
            print(s1.get('status'))
            print(s1.get('status'))
            print(s1.get('status'))
            # The spec requires final tag only; but we need to output only once:
            # We'll just output the tag once below
        if s2.get('status') != 'OK':
            print(f"{y2} Images: 0")
        # Choose the most specific failing code (C1 over C2 over C3). If either fails -> return that.
        fail_order = ['C1','C2','C3']
        for code in fail_order:
            if s1.get('status') == code or s2.get('status') == code:
                print(code)
                raise SystemExit(0)
        print("D")
        raise SystemExit(0)

    # Print concise stats for both years
    print(f"{y1} Images: {s1['images']}, Valid px: {s1['valid']}/{s1['base']} (masked: {s1['masked_pct']:.1f}%)")
    print(f"{y1} Veg px: {s1['veg_px']}, Veg frac: {s1['veg_frac']:.3f}")
    print(f"{y2} Images: {s2['images']}, Valid px: {s2['valid']}/{s2['base']} (masked: {s2['masked_pct']:.1f}%)")
    print(f"{y2} Veg px: {s2['veg_px']}, Veg frac: {s2['veg_frac']:.3f}")

    delta = s2['veg_frac'] - s1['veg_frac']
    print(f"Δ Veg frac (2019-1990): {delta:.3f}")

    # Final Answer
    if s2['veg_frac'] < s1['veg_frac']:
        print("A")
    else:
        print("B")

except ee.EEException as e:
    print("D")
except Exception as e:
    print("D")
